package io.tenvyr.control.runtime;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;

/** Intent commits before Git; the original operation owns recovery and terminal evidence. */
public final class WorkbenchReleaseWorkspace {
    private static final Set<String> ACTIVE=ConcurrentHashMap.newKeySet();
    private static final Map<String,ReentrantLock> DRIVERS=new HashMap<>();
    private final Db db;private final WorkspaceExecutionService leases;
    public WorkbenchReleaseWorkspace(Db db,WorkspaceExecutionService leases){this.db=db;this.leases=leases;}
    public ObjectNode release(JsonNode input){String key=WorkbenchCommandService.boundedKey(Json.text(input,"idempotencyKey")),target=Json.text(input,"workspaceExecutionId"),action="release-execution-workspace";ObjectNode payload=Json.object("workspaceExecutionId",target,"reason",input.get("reason"));if(Json.bytes(payload)>65536)throw fail("PAYLOAD_TOO_LARGE","Release payload exceeds bound");ObjectNode requested=db.transaction(tx->{tx.one("INSERT INTO operator_actions (action,\"idempotencyKey\",actor,\"targetId\",payload,outcome) VALUES (?,?,?,?,?,?) ON CONFLICT (action,\"idempotencyKey\") DO NOTHING RETURNING *",action,key,"local-operator",target,payload,Json.object("pending",true,"phase","REQUESTED"));ObjectNode row=tx.one("SELECT * FROM operator_actions WHERE action=? AND \"idempotencyKey\"=?",action,key);if(row==null)throw new IllegalStateException("Release intent disappeared");WorkbenchCommandService.assertSameRequestPayload(row.get("payload"),payload);return row;});JsonNode first=requested.path("outcome");if(!Json.bool(first,"pending",false)){if(Json.bool(first,"refusal",false))throw fail(Json.text(first,"failureCode","RELEASE_REFUSED"),"Release was refused");if(Json.text(first,"state","").equals("REMOVED"))return WorkbenchCommandService.receipt(action,key,"duplicate",first);if(!Json.bool(first,"retryRequired",false))throw fail("RELEASE_INTERRUPTED","Release requires operator retry");db.execute("UPDATE operator_actions SET outcome=? WHERE id=? AND outcome->>'state'='INTERRUPTED'",Json.object("pending",true,"phase","REQUESTED"),requested.get("id"));}
        ReentrantLock driver;synchronized(DRIVERS){driver=DRIVERS.computeIfAbsent(target,k->new ReentrantLock());if(!driver.tryLock())throw fail("OPERATION_IN_PROGRESS","Workspace release is already executing");}try{return drive(requested,target,action,key);}finally{driver.unlock();synchronized(DRIVERS){if(!driver.isLocked()&&!driver.hasQueuedThreads())DRIVERS.remove(target,driver);}}}
    private ObjectNode drive(ObjectNode requested,String target,String action,String key){ObjectNode chosen=db.transaction(tx->{ObjectNode lease=WorkspaceExecutionService.row(tx,target,true);if(Json.text(lease,"state").equals("REMOVED")){ObjectNode terminal=Json.object("workspaceExecutionId",target,"state","REMOVED");tx.execute("UPDATE operator_actions SET outcome=? WHERE action=? AND \"targetId\"=? AND outcome->>'pending'='true'",terminal,action,target);tx.execute("DELETE FROM workspace_release_locks WHERE \"workspaceExecutionId\"=?",target);return Json.object("terminal",terminal);}
            List<ObjectNode> pending=tx.query("SELECT * FROM operator_actions WHERE action=? AND \"targetId\"=? AND outcome->>'pending'='true' ORDER BY \"createdAt\",id FOR UPDATE",action,target);ObjectNode owner=null;String operation=Json.text(lease,"releaseOperationId",null);if(operation!=null)for(ObjectNode row:pending)if(Json.text(row,"id").equals(operation))owner=row;if(operation!=null&&owner==null)throw fail("RELEASE_UNAUTHORIZED","Workspace release has no authorizing operation");if(owner==null&&!pending.isEmpty())owner=pending.get(0);if(owner==null)throw fail("RELEASE_INTERRUPTED","Release intent is not pending");JsonNode outcome=owner.path("outcome");String phase=Json.text(outcome,"phase","");if(!Set.of("REQUESTED","EXECUTING").contains(phase))throw fail("RELEASE_UNAUTHORIZED","Release phase is invalid");String oldProcess=Json.text(outcome,"ownerProcessId",null),oldToken=Json.text(outcome,"ownerToken",null);if(phase.equals("EXECUTING")&&(oldProcess==null||oldToken==null))throw fail("RELEASE_UNAUTHORIZED","Release owner identity is missing");if(phase.equals("EXECUTING")&&WorkspaceExecutionService.PROCESS_INSTANCE_ID.equals(oldProcess)&&ACTIVE.contains(Json.text(owner,"id")+":"+oldToken))throw fail("OPERATION_IN_PROGRESS","Release owner is still active");String token=UUID.randomUUID().toString();ObjectNode executing=Json.object("pending",true,"phase","EXECUTING","ownerToken",token,"ownerProcessId",WorkspaceExecutionService.PROCESS_INSTANCE_ID,"claimedAt",Instant.now().toString());if(oldProcess!=null)executing.put("takenOverFrom",oldProcess);tx.update("operator_actions",Json.text(owner,"id"),Json.object("outcome",executing));owner.set("outcome",executing);ACTIVE.add(Json.text(owner,"id")+":"+token);return owner;});
        if(chosen.has("terminal"))return WorkbenchCommandService.receipt(action,key,"duplicate",chosen.get("terminal"));String op=Json.text(chosen,"id"),token=Json.text(chosen.path("outcome"),"ownerToken");WorkspaceExecutionService.ReleaseClaim claim=new WorkspaceExecutionService.ReleaseClaim(op,WorkspaceExecutionService.PROCESS_INSTANCE_ID,token);try{leases.releaseExecutionWorkspace(target,claim);ObjectNode current=db.one("SELECT outcome FROM operator_actions WHERE id=?",op);JsonNode terminal=current.path("outcome");if(Json.bool(terminal,"pending",false)||!Json.text(terminal,"state","").equals("REMOVED"))throw fail("RELEASE_INTERRUPTED","Release has no durable removal receipt");if(!op.equals(Json.text(requested,"id"))){ObjectNode recovered=(ObjectNode)terminal.deepCopy();recovered.put("recoveredOperationId",op);db.execute("UPDATE operator_actions SET outcome=? WHERE id=? AND outcome->>'pending'='true'",recovered,requested.get("id"));terminal=recovered;}return WorkbenchCommandService.receipt(action,key,"executed",terminal);}catch(RuntimeException error){ObjectNode current=db.one("SELECT * FROM operator_actions WHERE id=?",op);if(current!=null&&!Json.bool(current.path("outcome"),"pending",false)&&Json.bool(current.path("outcome"),"refusal",false)){if(!op.equals(Json.text(requested,"id")))db.execute("UPDATE operator_actions SET outcome=? WHERE id=? AND outcome->>'pending'='true'",current.get("outcome"),requested.get("id"));throw error;}db.transaction(tx->{ObjectNode lease=WorkspaceExecutionService.row(tx,target,true),row=tx.one("SELECT * FROM operator_actions WHERE id=? FOR UPDATE",op);JsonNode outcome=row==null?Json.object():row.path("outcome");if(Json.bool(outcome,"pending",false)&&Objects.equals(Json.text(outcome,"ownerToken",null),token)){ObjectNode recoverable=(ObjectNode)outcome.deepCopy();recoverable.put("phase","REQUESTED");recoverable.put("recoverable",true);recoverable.put("failedTerminal",true);tx.update("operator_actions",op,Json.object("outcome",recoverable));}return null;});throw error;}finally{ACTIVE.remove(op+":"+token);}}
    private static RuntimeFailure fail(String code,String message){return new RuntimeFailure(code,message);}
}
